-- Invented local fixtures only. Does NOT clone or attest production schema/data.
create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;
create role authenticator login noinherit;
do $$begin execute format('alter role authenticator password %L',(select rolpassword from pg_authid where rolname='postgres'));end $$;
grant anon,authenticated,service_role to authenticator;
create schema auth;
create function auth.uid() returns uuid language sql stable as $$select nullif(current_setting('request.jwt.claims',true)::json->>'sub','')::uuid$$;
grant usage on schema public,auth to anon,authenticated,service_role;
grant execute on function auth.uid() to anon,authenticated,service_role;
create table public.fixtures(fxid bigint primary key,lid bigint not null,lname text not null,lcountry text not null,date text not null,time text,status text not null,elapsed int,home text not null,away text not null,gh int,ga int,ft_h int,ft_a int,ht_h int,ht_a int,updated_at text,provider text,provider_blob jsonb);
create table public.predictions(fxid bigint primary key,lid bigint,lname text,home text,away text,pick text,pick_prob numeric,market text,p_home numeric,p_draw numeric,p_away numeric,xg_home numeric,xg_away numeric,kickoff text,ktime text,made_at text,withheld_at text,final_pick text,build int);
create table public.shared_records(key text primary key,payload jsonb,build int,computed_at text);
create table public.daily_slips(day text,tier text,odds numeric,build int,step text,legs jsonb);
create table public.odds_snapshots(fxid bigint,prices jsonb);
create table public.injuries(fxid bigint,raw jsonb);
create table public.match_context(fxid bigint,raw jsonb);
create table public.predictions_retired(fxid bigint,raw jsonb);
create table public.match_analysis(fxid bigint,raw jsonb);
create table public.venues(fxid bigint,raw jsonb);
create view public.fixtures_lean with(security_invoker=true) as select fxid,lid,date,time,status,elapsed,home,away,gh,ga,ft_h,ft_a,ht_h,ht_a from public.fixtures;
create view public.competitions with(security_invoker=true) as select distinct lid,lname,lcountry from public.fixtures;
create view public.odds_latest as select * from public.odds_snapshots;
create view public.provider_alias as select * from public.fixtures;
create table public.app_state(user_id uuid primary key,fav_leagues jsonb not null default '[]',fav_teams jsonb not null default '[]',fav_matches jsonb not null default '[]',record jsonb not null default '[]',prefs jsonb not null default '{}',updated_at timestamptz);
alter table public.app_state enable row level security;
grant select,insert,update,delete on public.app_state to authenticated;
create policy owned on public.app_state for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
do $$declare n text;begin foreach n in array array['fixtures','predictions','daily_slips','shared_records','odds_snapshots','injuries','match_context','predictions_retired','match_analysis','venues'] loop
 execute format('alter table public.%I enable row level security',n);
 execute format('create policy existing_public_read on public.%I for select using(true)',n);
 execute format('grant select on public.%I to public,anon,authenticated',n);
 execute format('grant insert,update,delete on public.%I to authenticated',n);
 execute format('grant select,insert,update,delete on public.%I to service_role',n);
 execute format('create policy existing_publisher_write on public.%I for all to authenticated using(auth.uid()=''%s'') with check(auth.uid()=''%s'')',n,'33333333-3333-4333-8333-333333333333','33333333-3333-4333-8333-333333333333');
end loop;end $$;
grant select on public.fixtures_lean,public.competitions,public.odds_latest,public.provider_alias to public,anon,authenticated;
grant select(provider_blob) on public.fixtures to anon;
